// 人物肖像素材清单（AI 生成的时代肖像，见 art-src/PORTRAIT_BIBLE.md）。
// 本文件由 tools/portraits/build.py 生成，不要手改；改元数据请改 art-src/portraits.json 后重新运行。
// 图片在 frontend/public/portraits/：<id>.webp 为 512×512 胸像，face/<id>.webp 为 256×256 脸部特写（缺原图的 LEGACY_PORTRAITS 仍是 256 / 128）。

export type PortraitGroup = "captain" | "mate" | "keeper" | "pirate" | "company" | "ruler" | "rival" | "informant" | "steward";

/** 人物的元数据（性别、年龄、文化、身份、设计要点，以及各组的 key）。 */
export interface PortraitMeta {
  /** 组内的 key：主角为外貌编号、航海士为 mates.toml 的 key、掌柜为“文化-设施-a/b/c”、君主为势力 key、商会为商会 key…… */
  key: string;
  gender: "male" | "female";
  age: number;
  /** 文化（七种建筑风格之一；主角可为 open 表示不限、elfkin 表示精裔） */
  culture: string;
  /** 身份（英文说明） */
  role: string;
  /** 中文设计要点 */
  design: string;
  /** 美少年型的成年男子 */
  androgynous?: boolean;
  /** 主角外貌编号（0–11、13–24；12 号空缺） */
  index?: number;
  /** 掌柜：设施与 a / b / c（每格三位） */
  facility?: string;
  variant?: "a" | "b" | "c";
  /** 君主与各国船长：势力 key */
  faction?: string;
}

/** 一位人物：id、组与元数据。 */
export interface PortraitEntry {
  id: string;
  group: PortraitGroup;
  meta: PortraitMeta;
}

/** 有图的人物。 */
export interface PortraitAsset extends PortraitEntry {
  /** 512×512 胸像（相对 public 的路径；LEGACY_PORTRAITS 里的为 256） */
  file: string;
  /** 256×256 脸部特写（LEGACY_PORTRAITS 里的为 128） */
  face: string;
}

export const PORTRAIT_SIZE = 512;
export const FACE_SIZE = 256;

