/** 圆：[中心 x, 中心 y, 半径]（输出图的像素）。 */
export type Circle = readonly [number, number, number];

/** 眨眼补丁：闭眼图的一块（带柔和透明边），贴在底图的 (x, y)。 */
export interface BlinkPatch {
  file: string;
  file2x?: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

/** 会动的头像的骨架（tools/portraits/live_rig.py）：一张形变权重图与两个支点，坐标是输出图的像素。 */
export interface LiveRig {
  /** 权重图（R 摆动、G 头部、B 呼吸；比底图小，放大着用） */
  file: string;
  /** 脸的圆：转头时五官在脸里的位移以它为界 */
  face: Circle;
  /** 颈根：头转动的支点 */
  neck: readonly [number, number];
}

export interface LiveArt {
  file: string;
  file2x?: string;
  width: number;
  height: number;
  blink: BlinkPatch;
  /** 眼镜镜片（反光扫过的位置） */
  lenses?: readonly Circle[];
  /** 有它才做网格形变（呼吸抬肩、转头、发梢摆动）；没有就只眨眼、整体伸缩 */
  rig?: LiveRig;
}

