/**
 * 人物立绘（portraits.json 的 figures 一节）：一个人站着、从头顶到膝上，透明底的竖幅。file 为 768×1152，small 为 384×576。
 * 头顶统一留出高度的 4.5%，底边切在膝上（人物贴着底边，叠在对话框或画面底部时脚下不留缝）；
 * box 是人物在大图里的范围 [x0, y0, x1, y1]（不透明度过半的像素，含手里的东西与飘出去的头发）。
 * key 是数据里人物的键；同一人多个年纪时按 fromAge 挑（与头像的 portraits 规则相同）。取图用 portraitCast.ts 的 figureOf / figureSrc。
 */
export interface FigureArt {
  id: string;
  key: string;
  fromAge: number;
  age: number;
  file: string;
  small: string;
  box: readonly [number, number, number, number];
}

export const FIGURE_SIZE: readonly [number, number] = [768, 1152];
export const FIGURE_SMALL_SIZE: readonly [number, number] = [384, 576];

