/** 动作帧条带：各帧横着排成一条（1 倍与 2 倍），width、height 是一帧的大小，frames 是各帧的名字。 */
export interface SpriteStrip {
  file: string;
  file2x: string;
  width: number;
  height: number;
  frames: readonly string[];
}

